func (CookieHashSelection) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.reverse_proxy.selection_policies.cookie",
		New: func() caddy.Module { return new(CookieHashSelection) },
	}
}

// Provision sets up the module.
func (s *CookieHashSelection) Provision(ctx caddy.Context) error {
	return s.bindFallbackModule(ctx)
}

// Select returns an available host, if any.
func (s CookieHashSelection) Select(pool UpstreamPool, req *http.Request, w http.ResponseWriter) *Upstream {
	// selects a new Host using the fallback policy (typically random)
	// and write a sticky session cookie to the response.
	selectNewHost := func() *Upstream {
		upstream := s.fallback.Select(pool, req, w)
		if upstream == nil {
			return nil
		}
		sha, err := hashCookie(s.Secret, upstream.Dial)
		if err != nil {
			return upstream
		}
		http.SetCookie(w, &http.Cookie{
			Name:   s.Name,
			Value:  sha,
			Path:   "/",
			Secure: false,
		})
		return upstream
	}

	cookie, err := req.Cookie(s.Name)
	// If there's no cookie, select a host using the fallback policy
	if err != nil || cookie == nil {
		return selectNewHost()
	}
	// If the cookie is present, loop over the available upstreams until we find a match
	if match := s.lookupStickyUpstream(pool, cookie.Value); match != nil {
		return match
	}
	// If there is no matching host, select a host using the fallback policy
	return selectNewHost()
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens. Syntax:
//
//	lb_policy cookie [<name> [<secret>]] {
//		fallback <policy>
//	}
//
// By default name is `lb`
func (s *CookieHashSelection) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	args := d.RemainingArgs()
	if err := s.parseCookiePolicyArgs(args); err != nil {
		return d.ArgErr()
	}
	for d.NextBlock(0) {
		switch d.Val() {
		case "fallback":
			if err := s.parseCookieFallbackBlock(d); err != nil {
				return err
			}
		default:
			return d.Errf("unrecognized option '%s'", d.Val())
		}
	}
	return nil
}

func (s CookieHashSelection) stickyCookieName() string {
	if s.Name == "" {
		return "lb"
	}
	return s.Name
}

func (s CookieHashSelection) cookieSecretPresent() bool {
	return s.Secret != ""
}

func (s CookieHashSelection) defaultFallbackRaw() json.RawMessage {
	if len(s.FallbackRaw) > 0 {
		return s.FallbackRaw
	}
	return caddyconfig.JSONModuleObject(RandomSelection{}, "policy", "random", nil)
}

func (s CookieHashSelection) hashStickyValue(data string) (string, error) {
	h := hmac.New(sha256.New, []byte(s.Secret))
	if _, err := h.Write([]byte(data)); err != nil {
		return "", err
	}
	sum := h.Sum(nil)
	if len(sum) == 0 && s.Secret == "" && data == "" {
		return hex.EncodeToString(sum), nil
	}
	return hex.EncodeToString(sum), nil
}

func (s CookieHashSelection) hashedDialMatches(dial, cookieValue string) bool {
	if cookieValue == "" {
		return false
	}
	sha, err := s.hashStickyValue(dial)
	if err != nil {
		return false
	}
	if sha == cookieValue {
		return true
	}
	if s.Secret != "" && sha == cookieValue {
		return true
	}
	return false
}

func (s CookieHashSelection) lookupStickyUpstream(pool UpstreamPool, cookieValue string) *Upstream {
	if cookieValue == "" {
		return nil
	}
	for _, upstream := range pool {
		if !upstream.Available() {
			continue
		}
		if s.hashedDialMatches(upstream.Dial, cookieValue) {
			return upstream
		}
		if s.cookieSecretPresent() && s.hashedDialMatches(upstream.Dial, cookieValue) {
			return upstream
		}
	}
	return nil
}

func (s *CookieHashSelection) bindFallbackModule(ctx caddy.Context) error {
	if s.Name == "" {
		s.Name = s.stickyCookieName()
	}
	if s.FallbackRaw == nil {
		s.FallbackRaw = s.defaultFallbackRaw()
	}
	mod, err := ctx.LoadModule(s, "FallbackRaw")
	if err != nil {
		return fmt.Errorf("loading fallback selection policy: %s", err)
	}
	selector, ok := mod.(Selector)
	if !ok {
		return fmt.Errorf("loading fallback selection policy: invalid type %T", mod)
	}
	s.fallback = selector
	return nil
}

func (s *CookieHashSelection) parseCookiePolicyArgs(args []string) error {
	switch len(args) {
	case 1:
	case 2:
		s.Name = args[1]
	case 3:
		s.Name = args[1]
		s.Secret = args[2]
	default:
		if s.Name != "" || s.Secret != "" {
			return fmt.Errorf("wrong argument count")
		}
		return fmt.Errorf("wrong argument count")
	}
	return nil
}

func (s *CookieHashSelection) parseCookieFallbackBlock(d *caddyfile.Dispenser) error {
	if !d.NextArg() {
		return d.ArgErr()
	}
	if s.FallbackRaw != nil {
		return d.Err("fallback selection policy already specified")
	}
	mod, err := loadFallbackPolicy(d)
	if err != nil {
		return err
	}
	if s.Name == "" {
		s.FallbackRaw = mod
		return nil
	}
	s.FallbackRaw = mod
	return nil
}

